"""Optional first editing pass, isolated from the normal project workflow."""
PANEL=r'''
<section class="panel" id="cutPassPanel"><details id="cutPassFold"><summary><b>✂ CUT · Primo montaggio opzionale</b><span class="muted"> Ripartenze, take e pause</span></summary>
<p class="muted">Propone i tagli sul video originale. Puoi ascoltare ogni take, cambiare la scelta e vedere il montaggio prima di confermarlo.</p>
<div class="row"><button id="cutAnalyze" type="button">ANALIZZA CUT</button><button id="cutPreview" type="button" disabled>GENERA ANTEPRIMA CUT</button><button id="cutConfirm" class="primary" type="button" disabled>CONFERMA CUT E CONTINUA</button></div>
<section id="cutProgress" role="status" aria-live="polite" data-state="idle"><div class="cutProgressTop"><span id="cutSpinner" aria-hidden="true" hidden></span><strong id="cutProgressLabel">CUT pronto</strong><span id="cutProgressPercent">0%</span><small id="cutProgressElapsed"></small></div><progress max="100" value="0" aria-label="Avanzamento CUT"></progress><p id="cutProgressDetail"></p><ol id="cutPhaseLog"></ol></section>
<p id="cutPlayerStatus" class="muted" hidden></p><video id="cutPlayer" controls hidden></video>

<p id="cutSummary"></p><p id="cutAlignmentWarnings" class="muted" role="status"></p><div class="row"><label>Pausa lunga (secondi) <input id="cutPause" type="number" min="0.5" max="5" step="0.1" value="1.2"></label><label>Respiro ai tagli <input id="cutBreath" type="number" min="0.05" max="0.5" step="0.01" value="0.18"></label><button id="cutSavePause" disabled>AGGIORNA PAUSE</button></div>
<details id="cutPhrasesFold"><summary><b>Frasi e take</b><span class="muted">Rivedi le scelte del montaggio</span></summary><div id="cutGroups"></div></details><details><summary>Testo dopo CUT</summary><p id="cutText"></p></details>
<details><summary>Diagnostica CUT</summary><button id="cutDebugCopy">COPIA DEBUG</button><pre id="cutDebug"></pre></details>
</details></section>
'''
CSS=r'''<style>
#cutPassPanel summary{cursor:pointer;padding:8px 0}#cutPassPanel summary span{margin-left:12px;font-size:12px}#cutProgress{display:flex;gap:12px;align-items:center;margin:14px 0;font-size:12px}#cutProgress progress{width:180px;height:7px;accent-color:var(--lime)}#cutGroups{display:grid;gap:10px;margin:12px 0}.cutGroup{padding:12px;border:1px solid var(--line);border-radius:10px;background:var(--p2)}.cutGroup header{display:flex;justify-content:space-between;gap:12px}.cutTake{display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:10px;padding:8px;border-radius:8px;align-items:center;margin-top:5px}.cutTake:has(input:checked){background:#7361a633;outline:1px solid #a995d8}.cutTake small{display:block}#cutPlayer{width:min(100%,420px);max-height:420px;background:#10131d;object-fit:contain;margin:12px 0}#cutDebug{max-height:220px;overflow:auto;white-space:pre-wrap;font-size:11px}#cutPassPanel input[type=number]{width:75px;padding:5px;background:var(--p2);color:var(--ink);border:1px solid var(--line);border-radius:6px}

#cutPhrasesFold{margin-top:12px}#cutGroups>.cutGroup{padding:0;overflow:hidden}.cutGroup>summary{display:flex;align-items:center;gap:12px;padding:13px 14px!important;list-style:none}.cutGroup>summary::-webkit-details-marker{display:none}.cutGroup>summary:before{content:'';width:8px;height:8px;flex:0 0 8px;border-right:2px solid var(--muted);border-bottom:2px solid var(--muted);transform:rotate(-45deg);transition:transform .15s}.cutGroup[open]>summary:before{transform:rotate(45deg)}#cutPassPanel .cutGroup>summary>span{margin-left:0;font-size:13px}.cutPhraseNumber{display:grid;place-items:center;min-width:25px;height:25px;border-radius:7px;background:#7361a633;color:#d9cbff;font-weight:800}.cutChosenPhrase{flex:1;min-width:0;line-height:1.5;font-weight:650}.cutGroup>summary>small{font-size:11px;white-space:nowrap}.cutGroupBody{padding:0 14px 14px;border-top:1px solid var(--line)}.cutGroupBody>p{font-size:12px;margin:10px 0}.cutPreviousTakes{margin:10px 0;border:1px solid var(--line);border-radius:8px;padding:0 8px}.cutPreviousTakes>summary{font-size:12px;font-weight:700}.cutPreviousTakes>summary small{margin-left:8px}.cutGroupChoices{display:flex;flex-wrap:wrap;gap:12px;font-size:12px;margin-top:12px}.cutDiscards>.cutTake{margin:6px 12px}.cutDiscards>summary{font-weight:650}@media(max-width:600px){.cutGroup>summary{flex-wrap:wrap}.cutGroup>summary>small{margin-left:47px}.cutTake{grid-template-columns:auto minmax(0,1fr)}.cutTake>button{grid-column:2;justify-self:start}}

#cutProgress{display:block;margin:14px 0;padding:14px 16px;border:1px solid var(--line);border-radius:12px;background:var(--p2)}.cutProgressTop{display:flex;align-items:center;gap:10px;flex-wrap:wrap}#cutProgressPercent{margin-left:auto;font-weight:800;font-variant-numeric:tabular-nums}#cutProgressElapsed{font-size:11px;color:var(--muted);font-variant-numeric:tabular-nums}#cutProgress progress{display:block;width:100%;height:9px;margin-top:12px;accent-color:var(--lime)}#cutProgressDetail{margin:9px 0 0;font-size:12px;line-height:1.5}#cutPhaseLog{margin:8px 0 0;padding-left:18px;color:var(--muted);font-size:11px;line-height:1.6}#cutPhaseLog:empty{display:none}#cutSpinner{width:15px;height:15px;border:2px solid #a3a8ba55;border-top-color:var(--lime);border-radius:50%;animation:cutSpinnerTurn .8s linear infinite}#cutSpinner[hidden]{display:none}#cutProgress[data-state=running]{border-color:#7971ae}#cutProgress[data-state=done]{border-color:#74a15b}#cutProgress[data-state=failed]{border-color:#c76d79}#cutProgress[data-state=failed] #cutProgressLabel{color:#ffbac1}#cutProgress[data-state=done] #cutProgressLabel{color:#b5e98e}@keyframes cutSpinnerTurn{to{transform:rotate(360deg)}}@media(prefers-reduced-motion:reduce){#cutSpinner{animation:none}}
</style>'''
JS=r'''
let cutPid=null,cutData=null,cutBusy=false,cutListenEnd=null,cutPollBusy=false,cutSourceKey=null;
const cutFoldStates=new Map();
const cutPlayer=$('cutPlayer');cutPlayer.ontimeupdate=()=>{if(cutListenEnd!=null&&cutPlayer.currentTime>=cutListenEnd){cutPlayer.pause();cutListenEnd=null}};
function cutFoldKey(g){return `${cutPid}:${g.takes.map(t=>t.join('-')).join(':')}`}
function rememberCutFolds(){for(const node of $('cutGroups').querySelectorAll('[data-cut-fold]'))cutFoldStates.set(node.dataset.cutFold,node.open)}
function bindCutFolds(){for(const node of $('cutGroups').querySelectorAll('[data-cut-fold]'))node.ontoggle=()=>cutFoldStates.set(node.dataset.cutFold,node.open)}
function cutTakeMarkup(g,i,t,busy){return `<label class="cutTake"><input type="radio" name="cut-${i}" data-group="${i}" value="${t}" ${g.selected_take===t?'checked':''} ${busy?'disabled':''}><span>${esc(g.texts[t])}<small>Take ${t+1} · ${g.source_ranges?.[t]?.start?.toFixed(1)||'?'}–${g.source_ranges?.[t]?.end?.toFixed(1)||'?'} s${g.selected_take===t?' · scelta':''}</small></span><button type="button" data-listen="${i}:${t}">ASCOLTA</button></label>`}
function cutGroupMarkup(g,i,busy){const key=cutFoldKey(g),selected=g.selected_take>=0?g.texts[g.selected_take]:g.selected_take===-2?'Gruppo scartato · '+g.texts[g.texts.length-1]:'Tutte le take · '+g.texts[0],others=g.texts.map((_,t)=>t).filter(t=>t!==g.selected_take);return `<details class="cutGroup" data-cut-fold="${esc(key)}" ${cutFoldStates.get(key)?'open':''}><summary><span class="cutPhraseNumber">${i+1}</span><span class="cutChosenPhrase">${esc(selected)}</span><small>${g.selected_take>=0?'Take '+(g.selected_take+1)+' scelta':g.selected_take===-2?'Scartato':'Tutte conservate'}</small></summary><div class="cutGroupBody"><p class="muted">${esc(g.reason)}</p>${g.selected_take>=0?cutTakeMarkup(g,i,g.selected_take,busy):''}<details class="cutPreviousTakes" data-cut-fold="${esc(key)}:alternatives" ${cutFoldStates.get(key+':alternatives')?'open':''}><summary>Take precedenti e alternative <small>${others.length} alternative</small></summary>${others.map(t=>cutTakeMarkup(g,i,t,busy)).join('')}</details><div class="cutGroupChoices"><label><input type="radio" name="cut-${i}" data-group="${i}" value="-1" ${g.selected_take===-1?'checked':''} ${busy?'disabled':''}> Conserva tutte le take</label><label><input type="radio" name="cut-${i}" data-group="${i}" value="-2" ${g.selected_take===-2?'checked':''} ${busy?'disabled':''}> Scarta il gruppo</label></div></div></details>`}
function cutProgressState(job={},pending=false){const active=pending||['starting','running'].includes(job.status),failed=job.status==='failed',done=job.status==='succeeded',percent=done?100:Math.max(0,Math.min(99,Math.round(Number(job.completed||0)/Number(job.total||4)*100))),limited=failed&&/429|rate limit/i.test(job.message||''),label=done?'✓ CUT completato':limited?'Limite temporaneo Groq':failed?'CUT non riuscito':active?'CUT in corso':'CUT pronto';return {active,failed,done,percent,label,state:failed?'failed':done?'done':active?'running':'idle'}}
function renderCutElapsed(){const job=cutData?.job||{};if(!job.started_at){$('cutProgressElapsed').textContent='';return}const end=job.finished_at||Date.now()/1000,seconds=Math.max(0,Math.floor(end-job.started_at));$('cutProgressElapsed').textContent=`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')} trascorsi`}
function renderCutProgress(job,busy){const view=cutProgressState(job,busy);$('cutProgress').dataset.state=view.state;$('cutProgress').setAttribute('aria-busy',String(view.active));$('cutSpinner').hidden=!view.active;$('cutProgressLabel').textContent=view.label;$('cutProgressPercent').textContent=view.percent+'%';$('cutProgress').querySelector('progress').value=view.percent;let message=job.message||'Avvia Analizza CUT per questo video';if(view.failed&&/429|rate limit/i.test(message)){const retry=message.match(/try again in ([\d.]+)/i);message='Il servizio Groq ha raggiunto il limite temporaneo. '+(retry?`Riprova dopo circa ${Math.ceil(Number(retry[1]))} secondi.`:'Riprova fra poco.')+' La trascrizione già completata resta salvata.'}$('cutProgressDetail').textContent=message;$('cutPhaseLog').innerHTML=(job.history||[]).slice(-5).map(e=>`<li>${esc(e.message)}</li>`).join('');renderCutElapsed()}
function drawCut(){const plan=cutData?.plan,job=cutData?.job||{},busy=job.status==='running'||cutBusy;for(const id of ['cutAnalyze','cutPreview','cutConfirm','cutSavePause'])$(id).disabled=busy||!!state.run||!state.project?.source_video|| (id!=='cutAnalyze'&&!plan);renderCutProgress(job,busy);$('cutAlignmentWarnings').textContent=(plan?.warnings||[]).join(' · ');$('cutDebug').textContent=JSON.stringify({project_id:cutPid,job,plan},null,2);if(!plan){$('cutSummary').textContent='';$('cutGroups').innerHTML='';$('cutText').textContent='';return}const rate=Number(plan.fps.split('/')[0])/Number(plan.fps.split('/')[1]||1);$('cutSummary').textContent=`${(plan.source_duration_frames/rate).toFixed(1)} s → ${plan.duration_seconds.toFixed(1)} s · ${plan.groups.length} gruppi di take · ${plan.alternatives.length} alternative conservate · ${plan.segments.length} parti mantenute`;$('cutPause').value=plan.pause_threshold;$('cutBreath').value=plan.breathing;$('cutText').textContent=cutData.text||'';rememberCutFolds();$('cutGroups').innerHTML=plan.groups.map((g,i)=>cutGroupMarkup(g,i,busy)).join('');bindCutFolds();$('cutGroups').querySelectorAll('[data-group]').forEach(input=>input.onchange=()=>saveCut({[input.dataset.group]:Number(input.value)}));$('cutGroups').querySelectorAll('[data-listen]').forEach(button=>button.onclick=async()=>{try{const pid=cutPid,[i,t]=button.dataset.listen.split(':').map(Number),r=await api(`/projects/${pid}/cut/words`);if(pid!==state.pid)return;const [a,b]=plan.groups[i].takes[t];$('source')?.pause();$('audioSource')?.pause();$('cutPlayerStatus').hidden=false;$('cutPlayerStatus').textContent='Ascolto della take originale';cutListenEnd=r.words[b].end;cutPlayer.hidden=false;cutPlayer.src=`/api/curation/projects/${pid}/media/source-video/source`;cutPlayer.onloadedmetadata=()=>{cutPlayer.currentTime=r.words[a].start;cutPlayer.play().catch(reportError)}}catch(e){reportError(e)}})}
function showCutPreview(url){$('source')?.pause();$('audioSource')?.pause();cutPlayer.pause();$('cutPlayerStatus').hidden=false;$('cutPlayerStatus').textContent='Montaggio pulito · premi Play per ascoltare dall’inizio';cutListenEnd=null;cutPlayer.onloadedmetadata=null;cutPlayer.hidden=false;cutPlayer.src=url;cutPlayer.load()}
async function refreshCut(){if(!state.pid||cutPollBusy)return;cutPollBusy=true;const pid=state.pid;try{const data=await api(`/projects/${pid}/cut`);if(pid!==state.pid)return;const changed=cutPid!==pid||cutData?.job?.id!==data.job?.id||cutData?.plan?.revision!==data.plan?.revision||cutData?.job?.status!==data.job?.status||cutData?.job?.completed!==data.job?.completed||cutData?.job?.updated_at!==data.job?.updated_at||cutData?.job?.message!==data.job?.message;cutPid=pid;cutData=data;if(changed){drawCut();if(data.job?.status==='succeeded'&&data.job?.result?.url&&data.job?.kind==='preview'){showCutPreview(data.job.result.url)}if(data.job?.status==='succeeded'&&data.job?.result?.project_id&&data.job?.kind==='confirm'){const next=data.job.result.project_id,p=await api(`/projects/${next}`);show(p,p.name,`/api/curation/projects/${next}/media/source-video/source`);if(typeof openOnlyWorkflowStepV42==='function')openOnlyWorkflowStepV42(2)}}}catch(e){if(pid===state.pid){$('cutProgressDetail').textContent=e.message}}finally{cutPollBusy=false}}
async function cutAction(action){if(!state.pid||cutBusy||cutData?.job?.status==='running')return;const pid=state.pid;cutBusy=true;cutData={...cutData,job:{id:'starting-'+Date.now(),kind:action,status:'starting',completed:0,total:4,started_at:Date.now()/1000,message:'Invio richiesta CUT…'}};$('cutPassFold').open=true;drawCut();$('cutProgress').scrollIntoView({block:'nearest',behavior:'smooth'});let accepted=false;try{const options={method:'POST'};if(action==='confirm'){options.headers={'Content-Type':'application/json'};options.body=JSON.stringify({revision:cutData.plan.revision})}const job=await api(`/projects/${pid}/cut/${action}`,options);if(pid===state.pid){cutData={...cutData,job};accepted=true;drawCut()}}catch(e){if(pid===state.pid)cutData={...cutData,job:{...cutData.job,status:'failed',message:e.message,finished_at:Date.now()/1000}}}finally{cutBusy=false;if(accepted)await refreshCut();drawCut()}}
async function saveCut(selected={},keepDisc={}){if(cutBusy||!cutData?.plan)return;cutBusy=true;const pid=cutPid;try{const value=await api(`/projects/${pid}/cut`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision:cutData.plan.revision,selected_takes:selected,keep_discards:keepDisc,pause_threshold:Number($('cutPause').value),breathing:Number($('cutBreath').value)})});if(pid===state.pid){cutData={...cutData,...value};cutPlayer.pause();cutPlayer.hidden=true;cutPlayer.removeAttribute('src')}}catch(e){reportError(e)}finally{cutBusy=false;drawCut()}}
const cutGroupDraw=drawCut;drawCut=function(){cutGroupDraw();const busy=cutData?.job?.status==='running'||cutBusy;if(busy)$('analyze').disabled=true;const rows=cutData?.plan?.discards||[];if(!rows.length)return;const box=document.createElement('details');box.className='cutGroup cutDiscards';const discardKey=cutPid+':discards';box.dataset.cutFold=discardKey;box.open=!!cutFoldStates.get(discardKey);box.ontoggle=()=>cutFoldStates.set(discardKey,box.open);box.innerHTML='<summary>Passaggi fuori scena e tentativi abbandonati <small>'+rows.length+' passaggi</small></summary>'+rows.map((d,i)=>`<label class="cutTake"><input type="checkbox" data-discard="${i}" ${d.keep?'checked':''} ${busy?'disabled':''}><span>${esc(d.text)}<small>${esc(d.reason)} · ${d.confidence<.85?'Da verificare':Math.round(d.confidence*100)+'%'} · spunta per conservare</small></span></label>`).join('');$('cutGroups').append(box);box.querySelectorAll('[data-discard]').forEach(input=>input.onchange=()=>saveCut({},{[input.dataset.discard]:input.checked}))};
$('cutAnalyze').onclick=()=>cutAction('analyze');$('cutPreview').onclick=()=>cutAction('preview');$('cutConfirm').onclick=()=>cutAction('confirm');$('cutSavePause').onclick=()=>saveCut();$('cutDebugCopy').onclick=()=>navigator.clipboard.writeText($('cutDebug').textContent).catch(reportError);
const cutDrawBase=draw;draw=function(){cutDrawBase();const sourceKey=state.pid+':'+(state.project?.source_video?.path||'')+':'+(state.project?.guide_audio?.signature||'');if(cutPid!==state.pid||cutSourceKey!==sourceKey){cutSourceKey=sourceKey;cutData=null;cutPid=state.pid;cutPlayer.pause();cutPlayer.hidden=true;cutPlayer.removeAttribute('src');drawCut();refreshCut()}else drawCut()};setInterval(refreshCut,900);setInterval(renderCutElapsed,1000);
'''
